def transform(grid):
    """Reflect the color-4 pattern vertically downward from its bottom edge."""
    h, w = len(grid), len(grid[0])
    cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    if not cells:
        return [row[:] for row in grid]
    bottom = max(r for r, _ in cells)
    out = [[0 if value == 6 else value for value in row] for row in grid]
    for r, c in cells:
        rr = 2 * bottom + 1 - r
        if 0 <= rr < h:
            out[rr][c] = 4
    return out

